import { initRuntime, registerServiceWorker } from './runtime.js';
import { FinanceAPI } from './api.js';
import { selectedCategory } from './classification.js';
import { prepareScheduleImport } from './import-parsers.js';
import { parseFinanceFile, exportWorkbook } from './excel.js';
import { buildReportSnapshot, calculateDashboard, productKrwValue } from './finance.js';
import { barChart, doughnutChart, lineChart, destroyAll } from './charts.js';
import {
  ROLE_LABELS, STATUS_LABELS, addDays, badge, clean, confirmDialog, downloadBlob, esc, fileSafe,
  firstDay, fmtDate, fmtDateTime, formDataObject, hideLoading, isoDate, lastDay, money, openModal,
  pct, shortMoney, showLoading, toast, toNumber
} from './utils.js';

const app=document.getElementById('app');
let runtime,api,session,profile,memberships=[],assignments=[],companies=[],activeCompany='all',currentPage='home';
let pendingFile=null,pendingParsed=null,recoveryMode=false,importing=false,scheduleRange=null;

const NAV=[
  ['home','⌂','오늘 할 일'],['bank_upload','⇧','은행자료 올리기'],['transactions','✓','확인할 거래'],
  ['schedules','◷','입금·지급 예정'],['accounts','▣','계좌·대출·예금'],['reports','▤','검토·보고'],
  ['approvals','☑','결재함'],['dashboard','▥','경영 대시보드'],['audit','↺','변경 이력'],['admin','⚙','관리자 설정']
];
const ROLE_PAGES={
  admin:NAV.map(x=>x[0]),
  finance_manager:['home','bank_upload','transactions','schedules','accounts','reports','approvals','dashboard','audit'],
  finance_staff:['home','bank_upload','transactions','schedules','accounts','reports','dashboard'],
  business_user:['home','bank_upload','transactions','schedules'],
  approver:['home','reports','approvals','dashboard'],
  executive:['home','reports','approvals','dashboard'],
  auditor:['home','reports','dashboard','audit'],
};

function canPage(page){
  if(profile?.role==='admin')return true;
  const explicit=assignments.filter(a=>a.module_code===page&&(a.company_id===null||a.company_id===activeCompany));
  if(explicit.length)return explicit.some(a=>a.can_view);
  return (ROLE_PAGES[profile?.role]||[]).includes(page);
}
function activeCompanyName(){if(activeCompany==='all')return '전체 법인';return companies.find(c=>c.id===activeCompany)?.name||'법인';}
function roleLabel(){return ROLE_LABELS[profile?.role]||profile?.role||'';}
function directionLabel(v){return v==='receipt'?'입금':v==='payment'?'지급':'계좌이체';}
function priorityLabel(v){return v==='high'?'높음':v==='low'?'낮음':'보통';}
function currencyAmount(value,currency='KRW'){const code=String(currency||'KRW').toUpperCase();return code==='KRW'?money(value):`${toNumber(value).toLocaleString('ko-KR',{maximumFractionDigits:4})} ${code}`}
function pageHeader(title,desc='',actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1>${desc?`<p>${desc}</p>`:''}</div><div class="page-actions">${actions}</div></div>`}
function emptyRow(cols,text='표시할 자료가 없습니다.'){return `<tr><td colspan="${cols}" class="table-empty">${esc(text)}</td></tr>`}
function companyOptions(selected=activeCompany,all=true){return `${all?`<option value="all" ${selected==='all'?'selected':''}>전체 법인</option>`:''}${companies.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}`}
async function runExport(name,sheets){try{showLoading('엑셀 파일을 만드는 중...');await exportWorkbook(name,sheets);toast('엑셀 파일을 저장했습니다.')}catch(e){toast(e.message||'엑셀 파일을 만들지 못했습니다.','error')}finally{hideLoading()}}

async function boot(){
  try{
    showLoading('재무관리 시스템을 시작하는 중...');
    runtime=await initRuntime(); api=new FinanceAPI(runtime);
    if(runtime.mode==='supabase')runtime.client.auth.onAuthStateChange((event,s)=>{session=s;if(event==='SIGNED_OUT')renderLogin();if(event==='PASSWORD_RECOVERY'){recoveryMode=true;setTimeout(renderPasswordRecovery,0);}});
    session=await api.getSession();
    if(recoveryMode)renderPasswordRecovery();else if(session)await enterApp();else renderLogin();
    registerServiceWorker();
  }catch(error){app.innerHTML=`<div style="padding:40px"><h2>시스템 시작 오류</h2><p>${esc(error.message)}</p><p>config.js를 수정한 뒤 GitHub에 반영하고 Netlify 배포 완료 후 새로고침하세요.</p></div>`;}
  finally{hideLoading()}
}

function renderLogin(){
  destroyAll();
  app.innerHTML=`<div class="login-shell"><section class="login-brand"><h1>입력보다 확인 중심의<br>재무관리</h1><p>현업 담당자가 각자의 업무를 등록하고, 재무팀이 수합·검토하며, 대표와 임원이 언제든 자금 위험과 결재 현황을 확인하는 통합 웹서비스입니다.</p><div class="login-features"><div class="login-feature">✓ 담당자별 역할·법인 권한 분리</div><div class="login-feature">✓ 은행자료·과거 자금계획서·기존 양식 이관</div><div class="login-feature">✓ 순차 결재·반려·보관·수정 이력</div><div class="login-feature">✓ 모바일·태블릿·PC 반응형 대시보드</div></div></section><section class="login-panel"><div class="login-card"><h2>로그인</h2><div class="hint">등록한 이메일과 비밀번호를 입력하세요. 처음 이용하시면 아래 이용 신청을 눌러 주세요.${runtime?.mode==='demo'?'<br><b>데모: 아무 이메일·비밀번호로 로그인할 수 있습니다.</b>':''}</div><form id="loginForm" class="form-stack"><div class="field"><label>이메일</label><input name="email" type="email" autocomplete="username" required value="${runtime?.mode==='demo'?'admin@demo.local':''}"></div><div class="field"><label>비밀번호</label><input name="password" type="password" autocomplete="current-password" required value="${runtime?.mode==='demo'?'demo':''}"></div><div id="loginError" class="login-error hidden"></div><button class="btn btn-primary btn-lg btn-block" type="submit">로그인</button><button class="btn btn-ghost btn-block" type="button" id="resetPasswordBtn">비밀번호 재설정 메일 보내기</button><button class="btn btn-secondary btn-block" type="button" id="requestAccessBtn">처음 이용하시는 분 · 이용 신청</button></form></div></section></div>`;
  document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();const f=formDataObject(e.currentTarget);const err=document.getElementById('loginError');err.classList.add('hidden');try{showLoading('로그인 중...');await api.signIn(f.email,f.password);session=await api.getSession();await enterApp();}catch(x){err.textContent=x.message;err.classList.remove('hidden')}finally{hideLoading()}};
  document.getElementById('requestAccessBtn').onclick=renderAccessRequest;
  document.getElementById('resetPasswordBtn').onclick=async()=>{const email=document.querySelector('[name=email]').value;if(!email)return toast('이메일을 먼저 입력하세요.','warn');try{await api.resetPassword(email);toast('비밀번호 재설정 메일을 보냈습니다.')}catch(e){toast(e.message,'error')}};
}

async function enterApp(){
  const user=session?.user||session;
  if(recoveryMode)return renderPasswordRecovery();
  if(!user?.id)return renderLogin();
  const device=await api.deviceStatus();
  if(device.status!=='approved')return renderDeviceGate(device);
  [profile,memberships,assignments,companies]=await Promise.all([api.getProfile(user.id),api.getMemberships(user.id),api.getModuleAssignments(user.id),api.listCompanies()]);
  if(profile?.active===false)throw new Error('비활성 사용자입니다. 관리자에게 문의하세요.');
  const allowed=new Set(memberships.map(m=>m.company_id));
  if(profile.role!=='admin')companies=companies.filter(c=>allowed.has(c.id));
  activeCompany=profile.default_company_id&&companies.some(c=>c.id===profile.default_company_id)?profile.default_company_id:(companies.length===1?companies[0].id:'all');
  if(!canPage(currentPage))currentPage='home';
  renderShell();await navigate(currentPage);
}

function renderShell(){
  app.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">₩</div><div><div class="brand-title">재무관리</div><div class="brand-sub">창진에스씨 통합 자금현황</div></div></div><nav class="nav" id="mainNav">${NAV.filter(([p])=>canPage(p)).map(([p,i,l])=>`<button data-page="${p}" class="${currentPage===p?'active':''}"><span class="nav-icon">${i}</span><span>${l}</span></button>`).join('')}</nav><div class="sidebar-footer"><div class="user-mini"><div class="user-avatar">${esc((profile.full_name||profile.email||'U').slice(0,1))}</div><div><div class="user-mini-name">${esc(profile.full_name||profile.email)}</div><div class="user-mini-role">${esc(roleLabel())}</div></div></div><button class="btn btn-ghost btn-sm btn-block" id="logoutBtn" style="color:#cde5f4;margin-top:10px">로그아웃</button></div></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="btn btn-ghost mobile-menu" id="mobileMenu">☰</button><select class="company-select" id="companySelector">${companyOptions()}</select><span class="period-chip">${new Intl.DateTimeFormat('ko-KR',{dateStyle:'long'}).format(new Date())}</span></div><div class="topbar-right"><span class="period-chip">${esc(profile.department||'')} ${esc(profile.job_title||'')}</span><button class="btn btn-secondary btn-sm" id="refreshBtn">새로고침</button></div></header><div class="content" id="content"></div></main></div>`;
  document.getElementById('mainNav').onclick=e=>{const b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page)};
  document.getElementById('companySelector').onchange=async e=>{activeCompany=e.target.value;await navigate(currentPage)};
  document.getElementById('logoutBtn').onclick=async()=>{await api.signOut();session=null;renderLogin()};
  document.getElementById('refreshBtn').onclick=()=>navigate(currentPage);
  document.getElementById('mobileMenu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');
}

async function navigate(page){
  if(!canPage(page)){toast('해당 메뉴 권한이 없습니다.','error');return}
  currentPage=page;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('sidebar')?.classList.remove('open');
  destroyAll();showLoading('자료를 불러오는 중...');
  try{const renderers={home:renderHome,bank_upload:renderUpload,transactions:renderTransactions,schedules:renderSchedules,accounts:renderAccounts,reports:renderReports,approvals:renderApprovals,dashboard:renderDashboard,audit:renderAudit,admin:renderAdmin};await renderers[page]();}
  catch(e){document.getElementById('content').innerHTML=pageHeader('오류')+`<div class="panel"><div class="negative">${esc(e.message)}</div></div>`;console.error(e)}finally{hideLoading()}
}

async function renderHome(){
  const from=addDays(isoDate(),-7),to=addDays(isoDate(),30);
  const [unreviewed,overdue,approvalCount,transactions,schedules]=await Promise.all([api.countTransactions(activeCompany),api.countOverdue(activeCompany),api.countApprovals(),api.listTransactions(activeCompany,{limit:8}),api.listSchedules(activeCompany,{fromDate:from,toDate:to})]);
  const connectionNeeded=schedules.filter(s=>s.status==='planned').length;
  document.getElementById('content').innerHTML=pageHeader('오늘은 3가지만 확인하세요',`${activeCompanyName()} 기준으로 미확인 거래, 예정과 실적 연결, 기한 경과 항목을 모았습니다.`,`<button class="btn btn-primary" data-go="bank_upload">은행 파일 올리기</button>`)+`
  <div class="grid grid-4"><div class="kpi-card"><div class="kpi-label">거래 분류 확인</div><div class="kpi-value">${unreviewed}건</div><div class="kpi-sub">미확인 은행거래</div></div><div class="kpi-card"><div class="kpi-label">예정과 실적 연결</div><div class="kpi-value">${connectionNeeded}건</div><div class="kpi-sub">연결 가능한 예정항목</div></div><div class="kpi-card"><div class="kpi-label">기한 지난 일정</div><div class="kpi-value ${overdue?'negative':''}">${overdue}건</div><div class="kpi-sub">입금·지급일 확인 필요</div></div><div class="kpi-card"><div class="kpi-label">내 결재 대기</div><div class="kpi-value">${approvalCount}건</div><div class="kpi-sub">승인 또는 반려 필요</div></div></div>
  <div class="grid grid-2" style="margin-top:16px"><section class="panel"><div class="panel-header"><div><h2 class="panel-title">확인이 필요한 거래</h2><div class="panel-sub">추천 분류를 확인한 뒤 저장합니다.</div></div><button class="btn btn-secondary btn-sm" data-go="transactions">전체 보기</button></div><div class="table-wrap"><table><thead><tr><th>일시</th><th>거래처·내용</th><th>입금</th><th>출금</th><th>상태</th></tr></thead><tbody>${transactions.length?transactions.map(t=>`<tr><td>${fmtDateTime(t.transaction_at)}</td><td>${esc(t.counterparty||t.bank_summary)}</td><td class="amount-in">${t.inflow?money(t.inflow):'-'}</td><td class="amount-out">${t.outflow?money(t.outflow):'-'}</td><td>${badge(t.classification_status)}</td></tr>`).join(''):emptyRow(5)}</tbody></table></div></section>
  <section class="panel"><div class="panel-header"><div><h2 class="panel-title">입금·지급 예정</h2><div class="panel-sub">오늘 기준 전후 일정입니다.</div></div><button class="btn btn-secondary btn-sm" data-go="schedules">일정 관리</button></div><div class="timeline">${schedules.length?schedules.slice(0,8).map(s=>`<div class="timeline-item"><div class="timeline-date">${fmtDate(s.due_date)}</div><div><b>${esc(s.counterparty||s.description)}</b><div class="small muted">${directionLabel(s.direction)} · ${priorityLabel(s.priority)}</div></div><div class="timeline-value ${s.direction==='receipt'?'positive':'negative'}">${money(s.amount)}</div></div>`).join(''):'<div class="table-empty">등록된 일정이 없습니다.</div>'}</div></section></div>
  <div class="panel"><div class="panel-header"><h2 class="panel-title">검토 전 확인</h2></div><div class="grid grid-3"><div class="card">✓ 계좌 잔고 기준일 확인</div><div class="card ${unreviewed?'warning':''}">! 미확인 거래 ${unreviewed}건</div><div class="card ${overdue?'negative':''}">! 기한 경과 일정 ${overdue}건</div></div></div>`;
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));
}

async function renderUpload(){
  const accounts=await api.listAccounts('all');
  document.getElementById('content').innerHTML=pageHeader('은행자료·기존자료 업로드','은행 거래내역, 기존 재무 입력양식, 과거 자금계획서를 자동 판별하여 가져옵니다.',`<button class="btn btn-secondary" id="legacyHelp">지원 양식 안내</button>`)+`
  <section class="panel"><div class="form-grid"><div class="field"><label>대상 법인</label><select id="uploadCompany">${companyOptions(activeCompany,false)}</select></div><div class="field"><label>대상 계좌(은행 거래내역일 때)</label><select id="uploadAccount"><option value="">계좌를 선택하세요</option>${accounts.map(a=>`<option value="${a.id}">${esc(a.bank_name)} · ${esc(a.account_name)} ${esc(a.account_number_masked||'')}</option>`).join('')}</select></div></div><div class="drop-zone" id="dropZone" style="margin-top:16px"><h3>엑셀·CSV 파일을 끌어다 놓으세요</h3><p>은행자료 / 기존 재무 입력양식 / 과거 자금계획서</p><label class="btn btn-primary" style="margin-top:14px">파일 선택<input type="file" id="uploadFile" accept=".xlsx,.xls,.csv,.json" hidden></label><div class="file-name" id="selectedFile"></div></div></section><div id="uploadPreview"></div>`;
  const chooseAccounts=()=>{const id=document.getElementById('uploadCompany').value;document.getElementById('uploadAccount').innerHTML='<option value="">계좌를 선택하세요</option>'+accounts.filter(a=>a.company_id===id).map(a=>`<option value="${a.id}">${esc(a.bank_name)} · ${esc(a.account_name)}</option>`).join('');};
  document.getElementById('uploadCompany').onchange=()=>{chooseAccounts();pendingParsed=null;pendingFile=null;document.getElementById('uploadPreview').innerHTML='';document.getElementById('selectedFile').textContent='법인이 변경되었습니다. 파일을 다시 선택하세요.';document.getElementById('uploadFile').value='';};chooseAccounts();
  const fileInput=document.getElementById('uploadFile'),zone=document.getElementById('dropZone');
  const handle=async file=>{if(!file||importing)return;pendingParsed=null;document.getElementById('uploadPreview').innerHTML='';pendingFile=file;document.getElementById('selectedFile').textContent=file.name;showLoading('파일 구조와 데이터를 분석하는 중...');try{const categories=await api.listCategories(document.getElementById('uploadCompany').value);pendingParsed=await parseFinanceFile(file,{categories});pendingParsed.categoryNames=Object.fromEntries(categories.map(c=>[c.id,c.name]));renderUploadPreview(pendingParsed)}catch(e){toast(e.message,'error');pendingParsed=null}finally{hideLoading()}};
  fileInput.onchange=e=>handle(e.target.files[0]);zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag')};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');handle(e.dataTransfer.files[0])};
  document.getElementById('legacyHelp').onclick=()=>openModal({title:'지원하는 파일 양식',body:`<div class="info-banner"><b>1. 은행 거래내역</b><br>기업·경남·농협·신한의 날짜·입금·출금 열을 자동 인식합니다. 제목·반복 머리글·합계·빈 행은 제외합니다. 잘못된 날짜·금액은 행 번호로 안내합니다.<br><br><b>2. 기존 재무현황 입력양식</b><br>자료구분·법인명으로 시작하는 34개 열 양식을 이관합니다.<br><br><b>3. 과거 자금계획서</b><br>‘YYYY년 MM월 조달 및 지출 계획’ 형식의 수입·지출 일정을 가져옵니다.<br><br><b>4. 기존 HTML JSON 백업</b><br>기존 재무현황표의 ‘데이터 백업 저장’에서 내려받은 JSON을 직접 이관합니다.</div>`});
}

function renderUploadPreview(parsed){
  const node=document.getElementById('uploadPreview');
  const kind={bank:'은행 거래내역',legacy:'기존 재무 입력양식',cash_plan:'과거 자금계획서'}[parsed.kind];
  let rows=[];
  if(parsed.kind==='bank')rows=parsed.preview.map(x=>({일시:fmtDateTime(x.transaction_at),내용:x.counterparty,입금:x.inflow,출금:x.outflow,잔액:x.balance,추천분류:parsed.categoryNames?.[x.suggested_category_id]||'확인 필요'}));
  if(parsed.kind==='cash_plan')rows=parsed.preview.map(x=>({예정일:x.due_date,구분:directionLabel(x.direction),내용:x.description,금액:x.amount,메모:x.memo}));
  if(parsed.kind==='legacy')rows=parsed.preview.map(x=>x);
  const cols=rows[0]?Object.keys(rows[0]):[];
  const summary=parsed.kind==='bank'?`거래 ${parsed.summary.total}건 · 입금 ${money(parsed.summary.inflow)} · 출금 ${money(parsed.summary.outflow)} · 제목/머리글 ${parsed.summary.headerRows}행, 합계/설명 등 ${parsed.summary.excluded}행 제외`:parsed.kind==='cash_plan'?`일정 ${parsed.summary.total}건 · 입금 ${money(parsed.summary.receipt)} · 지급 ${money(parsed.summary.payment)} · 이월/합계/금액 없음 ${parsed.summary.excluded}항목 제외`:JSON.stringify(parsed.summary);
  const planOptions=parsed.kind==='cash_plan'?`<div class="info-banner">원본은 ${parsed.summary.year}년 ${parsed.summary.month}월 계획서입니다. 적용 월을 바꾸면 일자는 유지하고 연월만 바꿉니다. 전월이월액은 일정으로 등록하지 않습니다. 내부이체·MMT 항목은 가져온 뒤 실제 성격을 확인하세요.</div><div class="field" style="margin:12px 0"><label>일정 적용 연월</label><input id="planTargetMonth" type="month" value="${parsed.summary.year}-${String(parsed.summary.month).padStart(2,'0')}" required></div>${parsed.warnings?.length?`<details><summary>제외·확인 사항 ${parsed.warnings.length}건 보기</summary><ul>${parsed.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}`:'';
  node.innerHTML=`<section class="panel"><div class="panel-header"><div><h2 class="panel-title">분석 결과: ${kind}</h2><div class="panel-sub">${esc(summary)}</div></div><button class="btn btn-primary" id="confirmImport">검토 후 가져오기</button></div>${planOptions}<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,50).map(r=>`<tr>${cols.map(c=>`<td>${typeof r[c]==='number'?money(r[c]):esc(r[c])}</td>`).join('')}</tr>`).join('')||emptyRow(cols.length)}</tbody></table></div><div class="small muted" style="margin-top:9px">미리보기는 최대 50건입니다. 실제 반영 전 법인·계좌·적용 연월을 확인하세요. 원본을 수정한 파일은 새 파일로 인식하므로 기존 일정과 중복 여부를 확인하세요.</div></section>`;
  document.getElementById('planTargetMonth')?.addEventListener('change',async()=>{
    try{const prepared=await prepareScheduleImport(parsed,document.getElementById('uploadCompany').value,profile.id,document.getElementById('planTargetMonth').value);node.querySelectorAll('tbody tr').forEach((tr,i)=>{if(prepared[i])tr.cells[0].textContent=prepared[i].due_date;});document.getElementById('confirmImport').disabled=false;}
    catch(e){document.getElementById('confirmImport').disabled=true;toast(e.message,'error',10000);}
  });
  document.getElementById('confirmImport').onclick=confirmImport;
}

async function confirmImport(){
  if(!pendingParsed||!pendingFile||importing)return;
  importing=true;
  const importButton=document.getElementById('confirmImport');if(importButton)importButton.disabled=true;
  const companyId=document.getElementById('uploadCompany').value,accountId=document.getElementById('uploadAccount').value;
  let batchId=null;
  try{showLoading('데이터를 저장하는 중...');
    if(!companyId)throw new Error('대상 법인을 선택하세요.');
    if(pendingParsed.kind==='bank'){
      if(!accountId)throw new Error('은행 거래내역은 대상 계좌를 선택해야 합니다.');
      const accounts=await api.listAccounts(companyId),acc=accounts.find(a=>a.id===accountId);
      if(!acc)throw new Error('선택한 법인에 속한 계좌를 선택하세요.');
      const path=await api.uploadOriginalFile(companyId,pendingFile);
      const batch=await api.createImportBatch({company_id:companyId,account_id:accountId,source_type:'bank_file',file_name:pendingFile.name,file_hash:pendingParsed.fileHash,storage_path:path,row_count:pendingParsed.rows.length,status:'processing'});batchId=batch.id;
      const rows=pendingParsed.rows.map(r=>({...r,company_id:companyId,account_id:accountId,source_hash:`${accountId}:${r.source_hash}`,import_batch_id:batch.id,owner_id:profile.id,created_by:profile.id}));
      const result=await api.bulkInsertTransactions(rows);await api.updateImportBatch(batch.id,{status:'completed',imported_count:result.inserted,duplicate_count:result.duplicates});
      const last=[...rows].filter(r=>r.balance!=null).sort((a,b)=>String(b.transaction_at).localeCompare(String(a.transaction_at)))[0];
      if(last&&(!acc.balance_as_of||new Date(last.transaction_at)>=new Date(acc.balance_as_of)))await api.saveAccount({...acc,current_balance:last.balance,balance_as_of:last.transaction_at});
      toast(`거래 ${result.inserted}건을 반영하고 중복 ${result.duplicates}건을 제외했습니다. 과거 자료는 더 최신인 현재잔고를 바꾸지 않습니다.`);
    }else if(pendingParsed.kind==='cash_plan'){
      const targetMonth=document.getElementById('planTargetMonth').value;
      if(!targetMonth)throw new Error('일정 적용 연월을 선택하세요.');
      const schedules=await prepareScheduleImport(pendingParsed,companyId,profile.id,targetMonth);
      const result=await api.importSchedules(schedules);
      const dates=schedules.map(x=>x.due_date).sort();scheduleRange={fromDate:dates[0],toDate:dates.at(-1)};
      toast(`자금계획 일정 ${result.inserted}건을 생성하고 기존 ${result.duplicates}건은 유지했습니다.`);
    }else{const result=await api.importLegacy(pendingParsed,companies);toast(`기존 자료를 이관했습니다: ${JSON.stringify(result)}`);}
    const destination=pendingParsed.kind==='cash_plan'?'schedules':'transactions';pendingFile=null;pendingParsed=null;await navigate(destination);
  }catch(e){
    if(batchId){try{await api.updateImportBatch(batchId,{status:'failed'});}catch{}}
    toast(`${e.message}${batchId?' 일부 저장되었을 수 있습니다. 같은 파일·계좌로 재시도하면 기존 거래는 유지합니다.':''}`,'error',12000);
  }finally{importing=false;if(importButton)importButton.disabled=false;hideLoading()}
}

async function renderTransactions(){
  const status=document.querySelector('#txStatus')?.value||'unreviewed',search=document.querySelector('#txSearch')?.value||'';
  const [rows,categories,schedules,people,history]=await Promise.all([api.listTransactions(activeCompany,{status:status==='all'?null:status,search,limit:500}),api.listCategories(activeCompany),api.listSchedules(activeCompany,{fromDate:addDays(isoDate(),-30),toDate:addDays(isoDate(),60)}),api.listProfiles(),api.listTransactions(activeCompany,{status:'reviewed',limit:1000})]);
  const selections=new Map(rows.map(t=>[t.id,selectedCategory(t,categories,history)]));
  document.getElementById('content').innerHTML=pageHeader('확인할 거래','확정 분류를 이전 확인내역과 키워드로 자동 선택합니다. 근거가 부족하면 기타로 선택하므로 확인 후 저장하세요.',`<button class="btn btn-secondary" id="txExport">엑셀 다운로드</button><button class="btn btn-primary" data-go="bank_upload">은행 파일 올리기</button>`)+`
  <section class="panel"><div class="filter-bar"><div class="field"><label>상태</label><select id="txStatus"><option value="unreviewed" ${status==='unreviewed'?'selected':''}>미확인</option><option value="reviewed" ${status==='reviewed'?'selected':''}>확인완료</option><option value="duplicate" ${status==='duplicate'?'selected':''}>중복후보</option><option value="all" ${status==='all'?'selected':''}>전체</option></select></div><div class="field wide"><label>검색</label><input id="txSearch" value="${esc(search)}" placeholder="거래처·적요·메모"></div><button class="btn btn-secondary" id="txFilter">조회</button><button class="btn btn-soft" id="bulkConfirm">선택 거래 확인완료</button></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="txAll"></th><th>거래일시</th><th>적요·거래처</th><th>입금</th><th>출금</th><th>추천 분류</th><th>확정 분류</th><th>예정 연결</th><th>담당</th><th>처리</th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr><td><input type="checkbox" class="tx-check" value="${t.id}"></td><td>${fmtDateTime(t.transaction_at)}</td><td><b>${esc(t.counterparty||'')}</b><div class="small muted">${esc(t.bank_summary||'')} ${esc(t.memo||'')}</div></td><td class="amount-in">${t.inflow?money(t.inflow):'-'}</td><td class="amount-out">${t.outflow?money(t.outflow):'-'}</td><td>${esc(t.suggested?.name||categories.find(c=>c.id===t.suggested_category_id)?.name||'-')}</td><td><select data-cat="${t.id}" title="${esc(selections.get(t.id)?.reason)}"><option value="">선택</option>${categories.filter(c=>!c.company_id||c.company_id===t.company_id).map(c=>`<option value="${c.id}" ${selections.get(t.id)?.id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><div class="small muted">${esc(selections.get(t.id)?.reason)}</div></td><td><select data-schedule="${t.id}"><option value="">연결 안함</option>${schedules.filter(s=>(t.inflow>0?s.direction==='receipt':s.direction!=='receipt')).map(s=>`<option value="${s.id}" ${t.matched_schedule_id===s.id?'selected':''}>${fmtDate(s.due_date)} ${esc(s.counterparty||s.description)} ${shortMoney(s.amount)}</option>`).join('')}</select></td><td><select data-owner="${t.id}"><option value="">미지정</option>${people.map(p=>`<option value="${p.id}" ${t.owner_id===p.id?'selected':''}>${esc(p.full_name||p.email)}</option>`).join('')}</select></td><td><div class="row-actions"><button class="btn btn-primary btn-sm" data-save-tx="${t.id}">확인</button><button class="btn btn-secondary btn-sm" data-history="${t.id}">이력</button></div></td></tr>`).join(''):emptyRow(10)}</tbody></table></div></section>`;
  document.getElementById('txStatus').onchange=()=>renderTransactions();document.getElementById('txFilter').onclick=()=>renderTransactions();document.getElementById('txSearch').onkeydown=e=>{if(e.key==='Enter')renderTransactions()};
  document.getElementById('txAll').onchange=e=>document.querySelectorAll('.tx-check').forEach(x=>x.checked=e.target.checked);
  document.querySelectorAll('[data-save-tx]').forEach(b=>b.onclick=async()=>{const id=b.dataset.saveTx;const category_id=document.querySelector(`[data-cat="${id}"]`).value||null;const matched_schedule_id=document.querySelector(`[data-schedule="${id}"]`).value||null;const owner_id=document.querySelector(`[data-owner="${id}"]`).value||null;try{await api.updateTransaction(id,{category_id,matched_schedule_id,owner_id,classification_status:'reviewed'});if(matched_schedule_id){const s=schedules.find(x=>x.id===matched_schedule_id);await api.saveSchedule({...s,status:'matched',matched_transaction_id:id})}toast('거래를 확인했습니다.');await renderTransactions()}catch(e){toast(e.message,'error')}});
  document.getElementById('bulkConfirm').onclick=async()=>{const ids=[...document.querySelectorAll('.tx-check:checked')].map(x=>x.value);if(!ids.length)return toast('거래를 선택하세요.','warn');showLoading('선택 거래를 처리하는 중...');try{for(const id of ids){const category_id=document.querySelector(`[data-cat="${id}"]`).value||null;await api.updateTransaction(id,{category_id,classification_status:'reviewed'})}toast(`${ids.length}건을 확인완료 처리했습니다.`);await renderTransactions()}catch(e){toast(e.message,'error')}finally{hideLoading()}};
  document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>showRecordHistory('bank_transactions',b.dataset.history));
  document.getElementById('txExport').onclick=()=>runExport(`거래내역_${fileSafe(activeCompanyName())}_${isoDate()}.xlsx`,{'거래내역':rows.map(t=>({거래일시:t.transaction_at,적요:t.bank_summary,거래처:t.counterparty,입금액:t.inflow,출금액:t.outflow,잔액:t.balance,분류:categories.find(c=>c.id===t.category_id)?.name||'',상태:STATUS_LABELS[t.classification_status]}))});
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));
}

async function renderSchedules(){
  const range=scheduleRange||{fromDate:addDays(isoDate(),-90),toDate:addDays(isoDate(),180)};
  const [rows,people]=await Promise.all([api.listSchedules(activeCompany,range),api.listProfiles()]);
  document.getElementById('content').innerHTML=pageHeader('입금·지급 예정','예정일과 실제 거래를 연결하고, 반복 일정을 관리합니다.',`<button class="btn btn-secondary" id="scheduleExport">엑셀 다운로드</button><button class="btn btn-secondary" id="uploadPlan">자금계획서 업로드</button><button class="btn btn-primary" id="addSchedule">일정 추가</button>`)+`<section class="panel"><div class="filter-bar"><div class="field"><label>조회 시작일</label><input id="scheduleFrom" type="date" value="${range.fromDate}"></div><div class="field"><label>조회 종료일</label><input id="scheduleTo" type="date" value="${range.toDate}"></div><button class="btn btn-secondary" id="filterSchedules">조회</button></div><div class="table-wrap"><table><thead><tr><th>예정일</th><th>구분</th><th>거래처·내용</th><th>금액</th><th>확률</th><th>우선순위</th><th>상태</th><th>담당</th><th>관리</th></tr></thead><tbody>${rows.length?rows.map(s=>`<tr><td>${fmtDate(s.due_date)}</td><td>${badge(s.direction,s.direction==='receipt'?'입금':s.direction==='payment'?'지급':'이체')}</td><td><b>${esc(s.counterparty||'')}</b><div class="small muted">${esc(s.description||'')}</div></td><td class="${s.direction==='receipt'?'amount-in':'amount-out'}">${money(s.amount)}</td><td>${s.direction==='receipt'?pct(s.probability):'-'}</td><td>${priorityLabel(s.priority)}</td><td>${badge(s.status)}</td><td>${esc(s.owner?.full_name|| (s.owner_id===profile.id?'나':'-'))}</td><td><div class="row-actions"><button class="btn btn-secondary btn-sm" data-edit-sch="${s.id}">수정</button><button class="btn btn-danger btn-sm" data-del-sch="${s.id}">삭제</button><button class="btn btn-secondary btn-sm" data-history="${s.id}">이력</button></div></td></tr>`).join(''):emptyRow(9)}</tbody></table></div></section>`;
  document.getElementById('uploadPlan').onclick=()=>navigate('bank_upload');
  document.getElementById('filterSchedules').onclick=()=>{const fromDate=document.getElementById('scheduleFrom').value,toDate=document.getElementById('scheduleTo').value;if(!fromDate||!toDate||fromDate>toDate)return toast('조회 시작일과 종료일을 확인하세요.','warn');scheduleRange={fromDate,toDate};renderSchedules();};
  document.getElementById('addSchedule').onclick=()=>scheduleModal({},people);document.querySelectorAll('[data-edit-sch]').forEach(b=>b.onclick=()=>scheduleModal(rows.find(x=>x.id===b.dataset.editSch),people));document.querySelectorAll('[data-del-sch]').forEach(b=>b.onclick=async()=>{if(await confirmDialog({title:'일정 삭제',message:'선택한 일정을 삭제하시겠습니까?',confirmText:'삭제',danger:true})){await api.deleteSchedule(b.dataset.delSch);toast('삭제했습니다.');renderSchedules()}});document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>showRecordHistory('schedules',b.dataset.history));
  document.getElementById('scheduleExport').onclick=()=>runExport(`입금지급예정_${fileSafe(activeCompanyName())}_${isoDate()}.xlsx`,{'일정':rows.map(s=>({예정일:s.due_date,구분:directionLabel(s.direction),거래처:s.counterparty,내용:s.description,금액:s.amount,입금확률:s.probability,우선순위:priorityLabel(s.priority),상태:STATUS_LABELS[s.status],메모:s.memo}))});
}

function scheduleModal(row={},people=[profile]){
  openModal({title:row.id?'일정 수정':'입금·지급 일정 추가',body:`<form id="scheduleForm" class="form-stack"><div class="form-grid"><div class="field"><label>법인</label><select name="company_id" required>${companyOptions(row.company_id||activeCompany,false)}</select></div><div class="field"><label>구분</label><select name="direction"><option value="receipt" ${row.direction==='receipt'?'selected':''}>입금</option><option value="payment" ${row.direction==='payment'?'selected':''}>지급</option><option value="transfer" ${row.direction==='transfer'?'selected':''}>계좌이체</option></select></div><div class="field"><label>예정일</label><input name="due_date" type="date" required value="${esc(row.due_date||isoDate())}"></div><div class="field"><label>금액</label><input name="amount" type="number" min="0" required value="${row.amount||''}"></div><div class="field"><label>거래처</label><input name="counterparty" value="${esc(row.counterparty||'')}"></div><div class="field"><label>우선순위</label><select name="priority"><option value="high" ${row.priority==='high'?'selected':''}>높음</option><option value="normal" ${!row.priority||row.priority==='normal'?'selected':''}>보통</option><option value="low" ${row.priority==='low'?'selected':''}>낮음</option></select></div><div class="field"><label>담당자</label><select name="owner_id">${people.map(p=>`<option value="${p.id}" ${(row.owner_id||profile.id)===p.id?'selected':''}>${esc(p.full_name||p.email)}</option>`).join('')}</select></div><div class="field"><label>입금확률(%)</label><input name="probability" type="number" min="0" max="100" value="${row.probability??100}"></div><div class="field"><label>상태</label><select name="status"><option value="planned">예정</option><option value="completed" ${row.status==='completed'?'selected':''}>완료</option><option value="cancelled" ${row.status==='cancelled'?'selected':''}>취소</option></select></div></div><div class="field"><label>내용</label><input name="description" value="${esc(row.description||'')}"></div><div class="field"><label>메모</label><textarea name="memo">${esc(row.memo||'')}</textarea></div></form>`,footer:`<button class="btn btn-secondary" data-modal-close>취소</button><button class="btn btn-primary" id="saveSchedule">저장</button>`,onOpen:(root,close)=>{root.querySelector('#saveSchedule').onclick=async()=>{const f=formDataObject(root.querySelector('#scheduleForm'));try{await api.saveSchedule({...row,...f,amount:toNumber(f.amount),probability:toNumber(f.probability),owner_id:f.owner_id||row.owner_id||profile.id,source:row.source||'manual'});close();toast('일정을 저장했습니다.');renderSchedules()}catch(e){toast(e.message,'error')}}}});
}

async function renderAccounts(){
  const [accounts,products,plans,assets]=await Promise.all([api.listAccounts(activeCompany),api.listProducts(activeCompany),api.listMonthlyPlans(activeCompany),api.listAssets(activeCompany)]);
  document.getElementById('content').innerHTML=pageHeader('계좌·대출·예금','계좌 잔고, 필수보유현금, 예·적금, 대출, 외화상품과 월별 자금계획을 관리합니다.',`<button class="btn btn-secondary" id="refreshRates">실시간 환율 반영</button><button class="btn btn-primary" id="addAccount">계좌 추가</button><button class="btn btn-soft" id="addProduct">금융상품 추가</button>`)+`
  <section class="panel"><div class="panel-header"><h2 class="panel-title">계좌 현황</h2></div><div class="table-wrap"><table><thead><tr><th>법인</th><th>은행</th><th>계좌명</th><th>계좌번호</th><th>현재잔고</th><th>필수보유현금</th><th>기준일시</th><th>관리</th></tr></thead><tbody>${accounts.length?accounts.map(a=>`<tr><td>${esc(companies.find(c=>c.id===a.company_id)?.name)}</td><td>${esc(a.bank_name)}</td><td>${esc(a.account_name)}</td><td>${esc(a.account_number_masked||'')}</td><td>${money(a.current_balance)}</td><td>${money(a.required_reserve)}</td><td>${fmtDateTime(a.balance_as_of)}</td><td><button class="btn btn-secondary btn-sm" data-edit-account="${a.id}">수정</button></td></tr>`).join(''):emptyRow(8)}</tbody></table></div></section>
  <section class="panel"><div class="panel-header"><div><h2 class="panel-title">대출·예금·외화상품</h2><div class="panel-sub">외화상품은 현재금액 × 적용환율로 원화환산합니다.</div></div></div><div class="table-wrap"><table><thead><tr><th>구분</th><th>은행·상품</th><th>통화</th><th>원금</th><th>현재금액</th><th>적용환율</th><th>원화환산</th><th>금리</th><th>만기일</th><th>중도해지</th><th>담보</th><th>관리</th></tr></thead><tbody>${products.length?products.map(p=>`<tr><td>${esc(p.product_type)}</td><td><b>${esc(p.bank_name||'')}</b> ${esc(p.product_name)}</td><td>${esc(p.currency)}</td><td>${currencyAmount(p.principal,p.currency)}</td><td>${currencyAmount(p.current_value,p.currency)}</td><td>${String(p.currency||'KRW').toUpperCase()==='KRW'?'-':toNumber(p.exchange_rate).toLocaleString('ko-KR',{maximumFractionDigits:6})}</td><td>${money(productKrwValue(p))}</td><td>${pct(p.interest_rate)}</td><td>${fmtDate(p.maturity_date)}</td><td>${p.redeemable?'가능':'불가'}</td><td>${p.pledged?'설정':'없음'}</td><td><button class="btn btn-secondary btn-sm" data-edit-product="${p.id}">수정</button></td></tr>`).join(''):emptyRow(12)}</tbody></table></div></section>
  <section class="panel"><div class="panel-header"><div><h2 class="panel-title">월별 수입·지출 계획</h2><div class="panel-sub">현재 연도 기준이며, 기존 재무양식 이관 시 자동 반영됩니다.</div></div><button class="btn btn-secondary btn-sm" id="editPlans">일괄 수정</button></div><div class="table-wrap"><table><thead><tr><th>월</th><th>수입</th><th>급여</th><th>외상대금</th><th>이자비용</th><th>기타비용</th><th>순현금흐름</th></tr></thead><tbody>${Array.from({length:12},(_,i)=>{const p=plans.find(x=>x.plan_month===i+1)||{};const expense=toNumber(p.salary)+toNumber(p.trade_payables)+toNumber(p.interest_expense)+toNumber(p.other_expense);return `<tr><td>${i+1}월</td><td>${money(p.income)}</td><td>${money(p.salary)}</td><td>${money(p.trade_payables)}</td><td>${money(p.interest_expense)}</td><td>${money(p.other_expense)}</td><td class="${toNumber(p.income)-expense>=0?'positive':'negative'}">${money(toNumber(p.income)-expense)}</td></tr>`}).join('')}</tbody></table></div></section>`;
  document.getElementById('refreshRates').onclick=async()=>{try{showLoading('실시간 환율을 확인하는 중...');const fx=await api.getExchangeRates();let updated=0;for(const p of products){const code=String(p.currency||'KRW').toUpperCase();const rate=toNumber(fx.rates?.[code]);if(code!=='KRW'&&rate>0){await api.saveProduct({...p,exchange_rate:rate});updated++}}toast(`환율 기준 ${fmtDateTime(fx.updated_at)} · 외화상품 ${updated}건 반영`);await renderAccounts()}catch(e){toast(`${e.message} 수동환율을 입력해 주세요.`,'warn')}finally{hideLoading()}};document.getElementById('addAccount').onclick=()=>accountModal();document.querySelectorAll('[data-edit-account]').forEach(b=>b.onclick=()=>accountModal(accounts.find(x=>x.id===b.dataset.editAccount)));document.getElementById('addProduct').onclick=()=>productModal();document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>productModal(products.find(x=>x.id===b.dataset.editProduct)));document.getElementById('editPlans').onclick=()=>plansModal(plans);
}

function accountModal(row={}){openModal({title:row.id?'계좌 수정':'계좌 추가',body:`<form id="accountForm" class="form-grid"><div class="field"><label>법인</label><select name="company_id">${companyOptions(row.company_id||activeCompany,false)}</select></div><div class="field"><label>은행</label><input name="bank_name" required value="${esc(row.bank_name||'')}"></div><div class="field"><label>계좌명</label><input name="account_name" required value="${esc(row.account_name||'운영계좌')}"></div><div class="field"><label>계좌번호(마스킹)</label><input name="account_number_masked" value="${esc(row.account_number_masked||'')}"></div><div class="field"><label>현재잔고</label><input name="current_balance" type="number" value="${row.current_balance||''}"></div><div class="field"><label>필수보유현금</label><input name="required_reserve" type="number" value="${row.required_reserve||''}"></div></form>`,footer:`<button class="btn btn-secondary" data-modal-close>취소</button><button class="btn btn-primary" id="saveAccount">저장</button>`,onOpen:(root,close)=>root.querySelector('#saveAccount').onclick=async()=>{const f=formDataObject(root.querySelector('#accountForm'));await api.saveAccount({...row,...f,current_balance:toNumber(f.current_balance),required_reserve:toNumber(f.required_reserve),currency:'KRW',active:true,balance_as_of:new Date().toISOString()});close();toast('계좌를 저장했습니다.');renderAccounts()}})}
function productModal(row={}){openModal({title:row.id?'금융상품 수정':'금융상품 추가',body:`<form id="productForm" class="form-grid"><div class="field"><label>법인</label><select name="company_id">${companyOptions(row.company_id||activeCompany,false)}</select></div><div class="field"><label>상품구분</label><select name="product_type"><option value="deposit">정기예금</option><option value="mmt">MMT</option><option value="mmf">MMF</option><option value="cma">CMA</option><option value="loan" ${row.product_type==='loan'?'selected':''}>대출</option><option value="fx_deposit" ${row.product_type==='fx_deposit'?'selected':''}>외화예금</option><option value="other">기타</option></select></div><div class="field"><label>은행</label><input name="bank_name" value="${esc(row.bank_name||'')}"></div><div class="field"><label>상품명</label><input name="product_name" required value="${esc(row.product_name||'')}"></div><div class="field"><label>통화</label><input name="currency" value="${esc(row.currency||'KRW')}"></div><div class="field"><label>원금</label><input name="principal" type="number" value="${row.principal||''}"></div><div class="field"><label>현재금액(해당 통화)</label><input name="current_value" type="number" step="any" value="${row.current_value||''}"></div><div class="field"><label>환율(1통화당 원화)</label><input name="exchange_rate" type="number" step="any" value="${row.exchange_rate||''}" placeholder="KRW는 0, USD 예: 1380"></div><div class="field"><label>금리(%)</label><input name="interest_rate" type="number" step="0.01" value="${row.interest_rate||''}"></div><div class="field"><label>가입일</label><input name="start_date" type="date" value="${esc(row.start_date||'')}"></div><div class="field"><label>만기일</label><input name="maturity_date" type="date" value="${esc(row.maturity_date||'')}"></div><div class="field"><label>중도해지</label><select name="redeemable"><option value="true" ${row.redeemable?'selected':''}>가능</option><option value="false" ${row.redeemable===false?'selected':''}>불가</option></select></div><div class="field"><label>담보·질권</label><select name="pledged"><option value="false">없음</option><option value="true" ${row.pledged?'selected':''}>있음</option></select></div></form>`,footer:`<button class="btn btn-secondary" data-modal-close>취소</button><button class="btn btn-primary" id="saveProduct">저장</button>`,onOpen:(root,close)=>root.querySelector('#saveProduct').onclick=async()=>{const f=formDataObject(root.querySelector('#productForm'));await api.saveProduct({...row,...f,principal:toNumber(f.principal),current_value:toNumber(f.current_value),exchange_rate:toNumber(f.exchange_rate),interest_rate:toNumber(f.interest_rate),redeemable:f.redeemable==='true',pledged:f.pledged==='true',active:true});close();toast('상품을 저장했습니다.');renderAccounts()}})}
function plansModal(plans){const year=new Date().getFullYear();openModal({title:`${year}년 월별 계획 일괄 수정`,width:'1000px',body:`<form id="plansForm"><div class="table-wrap"><table><thead><tr><th>월</th><th>수입</th><th>급여</th><th>외상대금</th><th>이자비용</th><th>기타비용</th></tr></thead><tbody>${Array.from({length:12},(_,i)=>{const p=plans.find(x=>x.plan_month===i+1)||{};return `<tr><td>${i+1}월</td><td><input name="income_${i+1}" type="number" value="${p.income||''}"></td><td><input name="salary_${i+1}" type="number" value="${p.salary||''}"></td><td><input name="pay_${i+1}" type="number" value="${p.trade_payables||''}"></td><td><input name="interest_${i+1}" type="number" value="${p.interest_expense||''}"></td><td><input name="other_${i+1}" type="number" value="${p.other_expense||''}"></td></tr>`}).join('')}</tbody></table></div></form>`,footer:`<button class="btn btn-secondary" data-modal-close>취소</button><button class="btn btn-primary" id="savePlans">저장</button>`,onOpen:(root,close)=>root.querySelector('#savePlans').onclick=async()=>{const f=formDataObject(root.querySelector('#plansForm'));const companyId=activeCompany==='all'?companies[0].id:activeCompany;const rows=Array.from({length:12},(_,i)=>({company_id:companyId,plan_year:year,plan_month:i+1,income:toNumber(f[`income_${i+1}`]),salary:toNumber(f[`salary_${i+1}`]),trade_payables:toNumber(f[`pay_${i+1}`]),interest_expense:toNumber(f[`interest_${i+1}`]),other_expense:toNumber(f[`other_${i+1}`])}));await api.upsertMonthlyPlans(rows);close();toast('월별 계획을 저장했습니다.');renderAccounts()}})}

async function renderReports(){
  const reports=await api.listReports(activeCompany);
  document.getElementById('content').innerHTML=pageHeader('검토·보고','자금현황을 스냅샷으로 저장하고 결재자를 지정하여 순차 결재 후 보관합니다.',`<button class="btn btn-primary" id="newReport">새 보고서</button>`)+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>보고서명</th><th>기간</th><th>작성자</th><th>버전</th><th>상태</th><th>결재 진행</th><th>작성일</th><th>관리</th></tr></thead><tbody>${reports.length?reports.map(r=>`<tr><td><b>${esc(r.title)}</b><div class="small muted">${esc(r.summary||'')}</div></td><td>${fmtDate(r.period_start)}~${fmtDate(r.period_end)}</td><td>${esc(r.creator?.full_name||'')}</td><td>v${r.current_version||0}</td><td>${badge(r.status)}</td><td>${(r.approval_steps||[]).sort((a,b)=>a.sequence_no-b.sequence_no).map(s=>`${s.sequence_no}. ${esc(s.approver?.full_name||'')} ${STATUS_LABELS[s.status]||s.status}`).join('<br>')||'-'}</td><td>${fmtDateTime(r.created_at)}</td><td><div class="row-actions"><button class="btn btn-secondary btn-sm" data-report="${r.id}">열기</button>${['draft','rejected'].includes(r.status)?`<button class="btn btn-soft btn-sm" data-edit-report="${r.id}">수정</button>`:''}${r.status==='approved'?`<button class="btn btn-soft btn-sm" data-archive="${r.id}">보관</button>`:''}</div></td></tr>`).join(''):emptyRow(8)}</tbody></table></div></section>`;
  document.getElementById('newReport').onclick=()=>reportModal();document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>reportDetail(b.dataset.report));document.querySelectorAll('[data-edit-report]').forEach(b=>b.onclick=()=>reportModal(reports.find(r=>r.id===b.dataset.editReport)));document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=async()=>{await api.archiveReport(b.dataset.archive);toast('승인 보고서를 보관했습니다.');renderReports()});
}

async function reportModal(row={}){
  const profiles=await api.listProfiles();const approvers=profiles.filter(p=>['approver','executive','finance_manager','admin'].includes(p.role));
  openModal({title:row.id?'보고서 수정':'새 자금현황 보고서',width:'900px',body:`<form id="reportForm" class="form-stack"><div class="form-grid"><div class="field"><label>법인</label><select name="company_id"><option value="">전체 법인</option>${companyOptions(row.company_id||activeCompany,false)}</select></div><div class="field"><label>보고 유형</label><select name="report_type"><option value="cash">자금현황</option><option value="weekly">주간</option><option value="monthly">월간</option><option value="ad_hoc">수시</option></select></div><div class="field"><label>시작일</label><input name="period_start" type="date" value="${row.period_start||firstDay()}" required></div><div class="field"><label>종료일</label><input name="period_end" type="date" value="${row.period_end||lastDay()}" required></div></div><div class="field"><label>보고서명</label><input name="title" value="${esc(row.title||`${new Date().getFullYear()}년 ${new Date().getMonth()+1}월 자금현황 보고`)}" required></div><div class="field"><label>요약·검토 요청사항</label><textarea name="summary">${esc(row.summary||'')}</textarea></div><div><b>결재자 선택 및 순서</b><div class="approver-order" style="margin-top:8px">${approvers.map((p,i)=>`<div class="approver-item"><input type="checkbox" name="approver" value="${p.id}"><span style="flex:1"><b>${esc(p.full_name)}</b> <span class="muted">${esc(ROLE_LABELS[p.role]||p.role)}</span></span><input type="number" name="order_${p.id}" value="${i+1}" min="1" style="width:70px"></div>`).join('')}</div></div></form>`,footer:`<button class="btn btn-secondary" data-modal-close>취소</button><button class="btn btn-soft" id="saveDraft">초안 저장</button><button class="btn btn-primary" id="submitReport">결재 요청</button>`,onOpen:(root,close)=>{
    const save=async submit=>{const f=formDataObject(root.querySelector('#reportForm'));const companyId=f.company_id||null;const data=await api.getDashboardData(companyId||'all');const snapshot=buildReportSnapshot(data,companyId||'all');const saved=await api.saveReport({...row,company_id:companyId,title:f.title,report_type:f.report_type,period_start:f.period_start,period_end:f.period_end,summary:f.summary,snapshot,status:row.status||'draft'});if(submit){const selected=[...root.querySelectorAll('[name=approver]:checked')].map(x=>({id:x.value,order:toNumber(root.querySelector(`[name="order_${x.value}"]`).value)})).sort((a,b)=>a.order-b.order).map(x=>x.id);if(!selected.length)throw new Error('결재자를 한 명 이상 선택하세요.');await api.submitReport(saved.id,selected)}close();toast(submit?'결재를 요청했습니다.':'초안을 저장했습니다.');renderReports()};
    root.querySelector('#saveDraft').onclick=async()=>{try{showLoading('보고서 스냅샷을 생성하는 중...');await save(false)}catch(e){toast(e.message,'error')}finally{hideLoading()}};root.querySelector('#submitReport').onclick=async()=>{try{showLoading('결재선을 생성하는 중...');await save(true)}catch(e){toast(e.message,'error')}finally{hideLoading()}};
  }});
}

async function reportDetail(id){const r=await api.getReport(id);const k=r.snapshot?.kpis||{};openModal({title:r.title,width:'1100px',body:`<div class="grid grid-4"><div class="kpi-card"><div class="kpi-label">현재 현금</div><div class="kpi-value">${shortMoney(k.current_cash)}</div></div><div class="kpi-card"><div class="kpi-label">30일 예상잔고</div><div class="kpi-value">${shortMoney(k.projected_balance)}</div></div><div class="kpi-card"><div class="kpi-label">선확보 필요</div><div class="kpi-value ${k.required_cash>0?'negative':''}">${shortMoney(k.required_cash)}</div></div><div class="kpi-card"><div class="kpi-label">투자가능</div><div class="kpi-value">${shortMoney(k.investable)}</div></div></div><section class="panel"><h2 class="panel-title">보고 요약</h2><p style="line-height:1.7">${esc(r.summary||'-')}</p></section><section class="panel"><h2 class="panel-title">결재선</h2><div class="approval-flow">${(r.approval_steps||[]).sort((a,b)=>a.sequence_no-b.sequence_no).map((s,i)=>`${i?'<span class="approval-arrow">→</span>':''}<div class="approval-step ${s.status==='pending'?'current':''}"><b>${s.sequence_no}. ${esc(s.approver?.full_name||'')}</b><div>${badge(s.status)}</div>${s.comment?`<div class="small muted">${esc(s.comment)}</div>`:''}</div>`).join('')||'결재선 없음'}</div></section><section class="panel"><h2 class="panel-title">버전 이력</h2>${(r.report_versions||[]).sort((a,b)=>b.version_no-a.version_no).map(v=>`<div class="card" style="margin-top:8px"><b>v${v.version_no}</b> · ${fmtDateTime(v.created_at)} · ${esc(v.change_reason||'수정')}</div>`).join('')||'<div class="muted">저장된 버전이 없습니다.</div>'}</section>`,footer:`<button class="btn btn-secondary" data-modal-close>닫기</button><button class="btn btn-secondary" id="exportReportDetail">엑셀 다운로드</button>`,onOpen:root=>root.querySelector('#exportReportDetail').onclick=()=>runExport(`${fileSafe(r.title)}.xlsx`,{'요약':[r.snapshot.kpis],'법인별':r.snapshot.entity_rows||[],'30일일정':r.snapshot.timeline||[],'월별계획':r.snapshot.monthly||[]})});}

async function renderApprovals(){const rows=await api.listApprovals();document.getElementById('content').innerHTML=pageHeader('결재함','나에게 지정된 순차 결재 요청을 승인하거나 반려합니다.')+`<div class="grid">${rows.length?rows.map(a=>`<section class="panel"><div class="panel-header"><div><h2 class="panel-title">${esc(a.reports?.title||'보고서')}</h2><div class="panel-sub">${fmtDate(a.reports?.period_start)} ~ ${fmtDate(a.reports?.period_end)} · 작성자 ${esc(a.reports?.creator?.full_name||'')}</div></div>${badge(a.status)}</div><div class="info-banner">${esc(a.reports?.summary||'검토 요청사항 없음')}</div><div class="grid grid-4" style="margin-top:14px"><div class="kpi-card"><div class="kpi-label">현재 현금</div><div class="kpi-value">${shortMoney(a.reports?.snapshot?.kpis?.current_cash)}</div></div><div class="kpi-card"><div class="kpi-label">예상잔고</div><div class="kpi-value">${shortMoney(a.reports?.snapshot?.kpis?.projected_balance)}</div></div><div class="kpi-card"><div class="kpi-label">선확보 필요</div><div class="kpi-value negative">${shortMoney(a.reports?.snapshot?.kpis?.required_cash)}</div></div><div class="kpi-card"><div class="kpi-label">결재 순번</div><div class="kpi-value">${a.sequence_no}차</div></div></div><div class="page-actions" style="margin-top:14px"><button class="btn btn-secondary" data-view-report="${a.report_id}">상세보기</button><button class="btn btn-danger" data-reject="${a.id}">반려</button><button class="btn btn-primary" data-approve="${a.id}">승인</button></div></section>`).join(''):'<div class="panel table-empty">현재 결재할 보고서가 없습니다.</div>'}</div>`;document.querySelectorAll('[data-view-report]').forEach(b=>b.onclick=()=>reportDetail(b.dataset.viewReport));document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approvalAction(b.dataset.approve,'approve'));document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>approvalAction(b.dataset.reject,'reject'));}
function approvalAction(id,action){openModal({title:action==='approve'?'보고서 승인':'보고서 반려',body:`<div class="field"><label>${action==='approve'?'승인 의견':'반려 사유(필수)'}</label><textarea id="approvalComment"></textarea></div>`,footer:`<button class="btn btn-secondary" data-modal-close>취소</button><button class="btn ${action==='approve'?'btn-primary':'btn-danger'}" id="confirmApproval">${action==='approve'?'승인':'반려'}</button>`,onOpen:(root,close)=>root.querySelector('#confirmApproval').onclick=async()=>{const comment=root.querySelector('#approvalComment').value;if(action==='reject'&&!comment.trim())return toast('반려 사유를 입력하세요.','warn');try{await api.actApproval(id,action,comment);close();toast(action==='approve'?'승인했습니다.':'반려했습니다.');renderApprovals()}catch(e){toast(e.message,'error')}}})}

async function renderDashboard(){
  const data=await api.getDashboardData(activeCompany),d=calculateDashboard(data,activeCompany);
  const risk=d.requiredCash>0?'위험':d.projected<d.requiredReserve?'주의':'안정';
  const backupButton=profile.role==='admin'?'<button class="btn btn-secondary" id="dashboardBackup">전체 백업</button>':'';
  document.getElementById('content').innerHTML=pageHeader('경영 대시보드','대표와 임원이 현재 유동성, 30일 자금전망, 법인별 부족액과 결재 대기를 한눈에 확인합니다.',`${backupButton}<button class="btn btn-secondary" id="printDashboard">인쇄·PDF</button><button class="btn btn-secondary" id="exportDashboard">엑셀 다운로드</button>`)+`
  <div class="grid grid-6"><div class="kpi-card"><div class="kpi-label">현재 가용자금</div><div class="kpi-value kpi-money">${money(d.currentCash)}</div><div class="kpi-sub">통장 잔고 합계</div></div><div class="kpi-card"><div class="kpi-label">30일 최저잔고</div><div class="kpi-value kpi-money ${d.minBalance<d.requiredReserve?'negative':''}">${money(d.minBalance)}</div><div class="kpi-sub">${d.minDate?`${fmtDate(d.minDate)} 예상`:'일정 기준'}</div></div><div class="kpi-card"><div class="kpi-label">추가 확보 필요</div><div class="kpi-value kpi-money ${d.requiredCash?'negative':''}">${money(d.requiredCash)}</div><div class="kpi-sub">지급 전 선확보 금액</div></div><div class="kpi-card"><div class="kpi-label">즉시·30일 유동화</div><div class="kpi-value kpi-money">${money(d.immediateLiquidity)}</div></div><div class="kpi-card"><div class="kpi-label">결재 대기</div><div class="kpi-value kpi-money">${d.pendingApprovals}건</div></div><div class="kpi-card"><div class="kpi-label">종합 상태</div><div class="kpi-value kpi-money ${risk==='안정'?'positive':risk==='주의'?'warning':'negative'}">${risk}</div><div class="kpi-sub">필수보유현금 기준</div></div></div>
  ${d.requiredCash>0?`<div class="alert-banner">⚠ 30일 일정 기준 ${money(d.requiredCash)}의 추가 자금 확보가 필요합니다.</div>`:''}
  <div class="grid grid-2"><div class="chart-card"><div class="panel-header"><h2 class="panel-title">월별 수입·지출 전망</h2></div><canvas id="monthlyFlowChart"></canvas></div><div class="chart-card"><div class="panel-header"><h2 class="panel-title">법인별 30일 예상잔고</h2></div><canvas id="entityChart"></canvas></div></div>
  <section class="panel" style="margin-top:16px"><div class="panel-header"><h2 class="panel-title">법인별 자금현황</h2></div><div class="table-wrap"><table><thead><tr><th>법인</th><th>현재잔고</th><th>필수보유현금</th><th>30일 입금</th><th>30일 지급</th><th>예상잔고</th><th>부족액</th><th>판단</th></tr></thead><tbody>${d.entityRows.map(r=>`<tr><td>${esc(r.company_name)}</td><td>${money(r.cash)}</td><td>${money(r.reserve)}</td><td class="positive">${money(r.receipt)}</td><td class="negative">${money(r.payment)}</td><td>${money(r.ending)}</td><td class="${r.shortage?'negative':'positive'}">${money(r.shortage)}</td><td>${r.shortage?`추가 확보 ${money(r.shortage)}`:`여유 ${money(r.surplus)}`}</td></tr>`).join('')}</tbody></table></div></section>
  <section class="panel"><div class="panel-header"><h2 class="panel-title">30일 주요 일정</h2></div><div class="timeline">${d.timeline.slice(0,12).map(x=>`<div class="timeline-item"><div class="timeline-date">${fmtDate(x.due_date)}</div><div><b>${esc(x.company_name)} · ${esc(x.counterparty||x.description)}</b><div class="small muted">${directionLabel(x.direction)} · 확률 ${x.probability}%</div></div><div class="timeline-value ${x.direction==='receipt'?'positive':'negative'}">${money(x.weighted_amount)}</div></div>`).join('')||'<div class="table-empty">예정 일정이 없습니다.</div>'}</div></section>`;
  try{await Promise.all([lineChart('monthlyFlowChart',d.monthly.map(x=>x.month),[{label:'수입',data:d.monthly.map(x=>x.income),borderColor:'#0796a0',backgroundColor:'#0796a0'},{label:'지출',data:d.monthly.map(x=>x.expense),borderColor:'#f59e0b',backgroundColor:'#f59e0b'}]),barChart('entityChart',d.entityRows.map(x=>x.company_name),[{label:'예상잔고',data:d.entityRows.map(x=>x.ending),backgroundColor:'#0796a0'},{label:'부족액',data:d.entityRows.map(x=>x.shortage),backgroundColor:'#e5484d'}])])}catch(e){toast('차트를 불러오지 못했습니다. 표 데이터는 정상적으로 사용할 수 있습니다.','warn')}
  document.getElementById('printDashboard').onclick=()=>window.print();document.getElementById('exportDashboard').onclick=()=>runExport(`경영대시보드_${fileSafe(activeCompanyName())}_${isoDate()}.xlsx`,{'KPI':[d],'법인별':d.entityRows,'30일일정':d.timeline,'월별':d.monthly});
  if(document.getElementById('dashboardBackup'))document.getElementById('dashboardBackup').onclick=async()=>{showLoading('전체 데이터를 백업하는 중...');try{const backup=await api.downloadBackup();downloadBlob(`창진재무_전체백업_${isoDate()}.json`,JSON.stringify(backup,null,2),'application/json;charset=utf-8');toast('전체 백업 파일을 저장했습니다.')}catch(e){toast(e.message,'error')}finally{hideLoading()}};
}

async function renderAudit(){const rows=await api.listAudit(activeCompany);document.getElementById('content').innerHTML=pageHeader('변경 이력','수정·삭제·승인·반려·보관 이력을 시간순으로 확인합니다.')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>일시</th><th>사용자</th><th>대상</th><th>작업</th><th>레코드</th><th>변경 요약</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${fmtDateTime(x.changed_at)}</td><td>${esc(x.changer?.full_name||x.changed_by||'-')}</td><td>${esc(x.table_name)}</td><td>${badge(x.action,x.action)}</td><td class="mono">${esc(x.record_id||'')}</td><td><button class="btn btn-secondary btn-sm" data-audit="${x.id}">상세</button></td></tr>`).join(''):emptyRow(6)}</tbody></table></div></section>`;document.querySelectorAll('[data-audit]').forEach(b=>b.onclick=()=>{const x=rows.find(r=>String(r.id)===b.dataset.audit);openModal({title:'변경 상세',width:'1000px',body:`<div class="grid grid-2"><div><b>변경 전</b><pre class="card mono" style="white-space:pre-wrap">${esc(JSON.stringify(x.old_data,null,2))}</pre></div><div><b>변경 후</b><pre class="card mono" style="white-space:pre-wrap">${esc(JSON.stringify(x.new_data,null,2))}</pre></div></div>`})})}
async function showRecordHistory(table,recordId){const rows=await api.listAudit(activeCompany,{tableName:table,recordId});openModal({title:'수정 이력',width:'1000px',body:rows.length?rows.map(x=>`<div class="card" style="margin-top:8px"><b>${fmtDateTime(x.changed_at)} · ${esc(x.action)}</b><div class="small muted">${esc(x.changer?.full_name||x.changed_by||'시스템')}</div><details style="margin-top:8px"><summary>변경내용 보기</summary><pre class="mono" style="white-space:pre-wrap">${esc(JSON.stringify({before:x.old_data,after:x.new_data},null,2))}</pre></details></div>`).join(''):'<div class="table-empty">변경 이력이 없습니다.</div>'})}

async function renderAdmin(){
  if(profile.role!=='admin')return;
  const [{users},categories,devices]=await Promise.all([api.adminListUsers(),api.listCategories(activeCompany),api.listDevices()]);
  document.getElementById('content').innerHTML=pageHeader('관리자 설정','사용자·역할·법인권한·결재자·분류 규칙·백업을 관리합니다.',`<button class="btn btn-secondary" id="backupBtn">전체 백업</button><label class="btn btn-warning">백업 복원<input type="file" id="restoreFile" accept=".json" hidden></label><button class="btn btn-primary" id="addUser">이용 신청 안내</button>`)+`
  <section class="panel"><h2>사용자 승인 대기</h2><p>신청자를 확인한 후 역할·법인 권한을 지정하세요. 기기 식별번호를 확인하면 선택한 기기를 함께 승인할 수 있습니다.</p><div class="table-wrap"><table><thead><tr><th>성명</th><th>이메일</th><th>부서</th><th>신청일</th><th>처리</th></tr></thead><tbody>${users.filter(u=>u.approval_status==='pending').map(u=>`<tr><td>${esc(u.full_name)}</td><td>${esc(u.email)}</td><td>${esc(u.department||'')}</td><td>${fmtDateTime(u.created_at)}</td><td><button class="btn btn-primary" data-approve-user="${u.id}">승인 및 권한 설정</button> <button class="btn btn-danger" data-reject-user="${u.id}">반려</button></td></tr>`).join('')||emptyRow(5,'승인 대기 신청이 없습니다.')}</tbody></table></div></section>
  <section class="panel"><h2>접속 기기 승인</h2><p>신청자의 기기 식별번호를 직접 확인한 후 승인하세요. 철회하면 다음 데이터 요청부터 차단됩니다.</p><div class="table-wrap"><table><thead><tr><th>사용자</th><th>기기 이름</th><th>식별번호</th><th>상태</th><th>관리</th></tr></thead><tbody>${devices.map(d=>`<tr><td>${esc(d.email)}</td><td>${esc(d.label)}</td><td>${esc(d.id)}</td><td>${esc(({pending:'승인 대기',approved:'승인',revoked:'철회'})[d.status])}</td><td><button class="btn btn-secondary" data-device="${d.id}" data-status="approved">승인</button> <button class="btn btn-danger" data-device="${d.id}" data-status="revoked">철회</button></td></tr>`).join('')}</tbody></table></div></section>
  <section class="panel"><div class="panel-header"><h2 class="panel-title">사용자와 권한</h2></div><div class="table-wrap"><table><thead><tr><th>성명</th><th>이메일</th><th>부서·직위</th><th>역할</th><th>법인 권한</th><th>상태</th><th>최근 로그인</th><th>관리</th></tr></thead><tbody>${users.map(u=>`<tr><td><b>${esc(u.full_name||'-')}</b></td><td>${esc(u.email||'')}</td><td>${esc(u.department||'')} ${esc(u.job_title||'')}</td><td>${esc(ROLE_LABELS[u.role]||u.role)}</td><td>${(u.memberships||[]).map(m=>`${esc(m.companies?.name||companies.find(c=>c.id===m.company_id)?.name||'')}(${esc(m.access_level)})`).join('<br>')||'-'}</td><td>${u.approval_status==='pending'?badge('pending','승인 대기'):u.approval_status==='rejected'?badge('rejected','반려'):u.active===false?badge('inactive','비활성'):badge('active','사용')}</td><td>${fmtDateTime(u.last_sign_in_at)}</td><td><div class="row-actions"><button class="btn btn-secondary btn-sm" data-edit-user="${u.id}">수정</button><button class="btn ${u.active===false?'btn-soft':'btn-danger'} btn-sm" data-toggle-user="${u.id}" ${u.approval_status&&u.approval_status!=='approved'?'disabled':''}>${u.active===false?'활성화':'비활성'}</button></div></td></tr>`).join('')}</tbody></table></div></section>
  <section class="panel"><div class="panel-header"><div><h2 class="panel-title">거래 분류·추천 키워드</h2><div class="panel-sub">은행 거래내용에 키워드가 포함되면 추천 분류로 표시됩니다.</div></div><button class="btn btn-soft" id="addCategory">분류 추가</button></div><div class="table-wrap"><table><thead><tr><th>분류명</th><th>방향</th><th>키워드</th><th>사용</th><th>관리</th></tr></thead><tbody>${categories.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.direction)}</td><td>${esc((c.keywords||[]).join(', '))}</td><td>${c.active?'사용':'중지'}</td><td><button class="btn btn-secondary btn-sm" data-edit-cat="${c.id}">수정</button></td></tr>`).join('')}</tbody></table></div></section>`;
  document.querySelectorAll('[data-device]').forEach(b=>b.onclick=async()=>{if(!await confirmDialog({title:'기기 상태 변경',message:'이 기기의 접속 상태를 변경하시겠습니까?',confirmText:'변경'}))return;try{await api.setDevice(b.dataset.device,b.dataset.status);await enterApp();}catch(e){toast(e.message,'error')}});
  document.getElementById('addUser').onclick=()=>openModal({title:'이용 신청 안내',body:'<p>직원이 사이트 로그인 화면의 이용 신청에서 이메일·비밀번호·성명·부서를 입력합니다. 이메일 확인 후 로그인하여 기기를 등록하면 이 화면에서 사용자와 기기를 승인할 수 있습니다.</p><p>이미 로그인 계정이 있는 직원은 새로 가입하지 않고 기존 계정으로 로그인하세요.</p>'});
  document.querySelectorAll('[data-approve-user]').forEach(b=>b.onclick=()=>userModal({...users.find(u=>u.id===b.dataset.approveUser),active:true},devices));
  document.querySelectorAll('[data-reject-user]').forEach(b=>b.onclick=async()=>{if(!await confirmDialog({title:'이용 신청 반려',message:'이 사용자의 이용 신청을 반려하고 기기를 철회하시겠습니까?',confirmText:'반려',danger:true}))return;try{await api.rejectUser(b.dataset.rejectUser);await renderAdmin();}catch(e){toast(e.message,'error')}});
  document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>userModal(users.find(u=>u.id===b.dataset.editUser),devices));document.querySelectorAll('[data-toggle-user]').forEach(b=>b.onclick=async()=>{const u=users.find(x=>x.id===b.dataset.toggleUser);const next=u.active===false;const ok=await confirmDialog({title:next?'사용자 활성화':'사용자 비활성화',message:next?'로그인과 업무 사용을 다시 허용합니다.':'재무자료 접근을 차단하되 작성·결재·변경 이력은 보존합니다.',confirmText:next?'활성화':'비활성',danger:!next});if(!ok)return;try{await api.adminUpdateUser({user_id:u.id,active:next});toast(next?'사용자를 활성화했습니다.':'사용자를 비활성화했습니다.');renderAdmin()}catch(e){toast(e.message,'error')}});
  document.getElementById('backupBtn').onclick=async()=>{showLoading('전체 데이터를 백업하는 중...');try{const backup=await api.downloadBackup();downloadBlob(`창진재무_전체백업_${isoDate()}.json`,JSON.stringify(backup,null,2),'application/json;charset=utf-8');toast('백업 파일을 저장했습니다.')}catch(e){toast(e.message,'error')}finally{hideLoading()}};
  document.getElementById('restoreFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!await confirmDialog({title:'전체 백업 복원',message:'동일한 ID의 자료를 덮어쓸 수 있습니다. 복원하시겠습니까?',confirmText:'복원',danger:true}))return;showLoading('백업을 복원하는 중...');try{const backup=JSON.parse(await file.text());await api.restoreBackup(backup);toast('백업 복원이 완료되었습니다.');renderAdmin()}catch(x){toast(x.message,'error')}finally{hideLoading();e.target.value=''}};
  document.getElementById('addCategory').onclick=()=>categoryModal();document.querySelectorAll('[data-edit-cat]').forEach(b=>b.onclick=()=>categoryModal(categories.find(c=>c.id===b.dataset.editCat)));
}

function userModal(row={},devices=[]){row={role:'business_user',...row};const approving=row.approval_status==='pending'||row.approval_status==='rejected';const currentMemberships=new Map((row.memberships||[]).map(m=>[m.company_id,m.access_level]));openModal({title:approving?'사용자 승인 및 권한 설정':'사용자 수정',width:'900px',body:`<form id="userForm" class="form-stack"><div class="form-grid"><div class="field"><label>성명</label><input name="full_name" required value="${esc(row.full_name||'')}"></div><div class="field"><label>이메일</label><input name="email" type="email" required value="${esc(row.email||'')}"></div><div class="hint">직원이 신청한 계정의 업무 권한을 설정합니다. 비밀번호는 로그인 화면의 재설정 메일로 변경할 수 있습니다.</div><div class="field"><label>역할</label><select name="role">${Object.entries(ROLE_LABELS).map(([k,v])=>`<option value="${k}" ${row.role===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>부서</label><input name="department" value="${esc(row.department||'')}"></div><div class="field"><label>직위</label><input name="job_title" value="${esc(row.job_title||'')}"></div><div class="field"><label>계정 상태</label><label class="check-line"><input type="checkbox" name="active" ${row.active!==false?'checked':''}> 사용 가능</label></div></div>${approving?`<div class="field"><label>함께 승인할 기기</label><select name="approve_device"><option value="">기기는 나중에 별도 승인</option>${devices.filter(d=>d.user_id===row.id&&d.status==='pending').map(d=>`<option value="${d.id}">${esc(d.label)} / ${esc(d.id)}</option>`).join('')}</select><p class="hint">신청자가 알려 준 식별번호와 일치하는 기기만 선택하세요. 선택하지 않으면 사용자 승인 후 기기 승인이 별도로 필요합니다.</p></div>`:''}<div><b>법인별 접근권한</b><div class="grid grid-3" style="margin-top:8px">${companies.map(c=>`<div class="card"><label><input type="checkbox" name="company" value="${c.id}" ${currentMemberships.has(c.id)?'checked':''}> ${esc(c.name)}</label><select name="access_${c.id}" style="width:100%;margin-top:8px"><option value="read" ${currentMemberships.get(c.id)==='read'?'selected':''}>조회</option><option value="contribute" ${currentMemberships.get(c.id)==='contribute'?'selected':''}>현업 입력</option><option value="finance" ${currentMemberships.get(c.id)==='finance'?'selected':''}>재무 관리</option><option value="manage" ${currentMemberships.get(c.id)==='manage'?'selected':''}>전체 관리</option></select></div>`).join('')}</div></div></form>`,footer:`<button class="btn btn-secondary" data-modal-close>취소</button><button class="btn btn-primary" id="saveUser">저장</button>`,onOpen:(root,close)=>root.querySelector('#saveUser').onclick=async()=>{const f=formDataObject(root.querySelector('#userForm'));const selected=[...root.querySelectorAll('[name=company]:checked')].map(x=>({company_id:x.value,access_level:root.querySelector(`[name="access_${x.value}"]`).value}));const payload={email:f.email,full_name:f.full_name,password:f.password||undefined,role:f.role,department:f.department,job_title:f.job_title,active:root.querySelector('[name=active]').checked,default_company_id:selected[0]?.company_id||null,memberships:selected};try{if(approving)await api.approveUser({user_id:row.id,...payload,device_id:f.approve_device||null});else await api.adminUpdateUser({user_id:row.id,...payload});close();toast('사용자와 권한을 저장했습니다.');renderAdmin()}catch(e){toast(e.message,'error')}}})}
function categoryModal(row={}){openModal({title:row.id?'분류 수정':'분류 추가',body:`<form id="catForm" class="form-stack"><div class="field"><label>분류명</label><input name="name" required value="${esc(row.name||'')}"></div><div class="field"><label>거래 방향</label><select name="direction"><option value="mixed">혼합</option><option value="receipt" ${row.direction==='receipt'?'selected':''}>입금</option><option value="payment" ${row.direction==='payment'?'selected':''}>지급</option><option value="transfer" ${row.direction==='transfer'?'selected':''}>이체</option></select></div><div class="field"><label>추천 키워드(쉼표 구분)</label><textarea name="keywords">${esc((row.keywords||[]).join(', '))}</textarea></div><div class="field"><label><input type="checkbox" name="active" ${row.active!==false?'checked':''}> 사용</label></div></form>`,footer:`<button class="btn btn-secondary" data-modal-close>취소</button><button class="btn btn-primary" id="saveCat">저장</button>`,onOpen:(root,close)=>root.querySelector('#saveCat').onclick=async()=>{const f=formDataObject(root.querySelector('#catForm'));await api.saveCategory({...row,company_id:row.company_id||null,name:f.name,direction:f.direction,keywords:String(f.keywords||'').split(',').map(clean).filter(Boolean),active:root.querySelector('[name=active]').checked,sort_order:row.sort_order||100});close();toast('분류를 저장했습니다.');renderAdmin()}})}

function renderDeviceGate(device){
 destroyAll();
 const deviceState=device.device_status||device.status;
 const blocked=['user_rejected','inactive'].includes(device.status);
 app.innerHTML=`<div class="login-shell"><section class="login-panel"><div class="login-card"><h2>관리자 승인 후 이용할 수 있습니다</h2><p>사용자 상태: ${esc(({pending:'승인 대기',approved:'승인 완료',rejected:'신청 반려'})[device.approval_status]||'계정 확인 완료')}</p><p>접속 상태: ${esc(({unregistered:'기기 미등록',pending:'기기 승인 대기',revoked:'기기 승인 철회',inactive:'계정 비활성',user_pending:'사용자 승인 대기',user_rejected:'신청 반려'})[device.status]||device.status)}</p><p>기기 식별번호: ${esc(device.id||'등록 신청 후 표시됩니다.')}</p><p>아래에서 기기를 등록하고 표시된 식별번호를 회사 관리자에게 알려 주세요. 관리자가 프로그램의 관리자 설정에서 승인합니다.</p><form id="deviceForm"><label>기기 이름</label><input name="label" required maxlength="80" placeholder="예: 재무팀 업무용 PC / Edge"><button class="btn btn-primary" ${blocked||deviceState!=='unregistered'?'disabled':''}>기기 등록 신청</button></form><button class="btn btn-secondary" id="checkDevice">승인 여부 다시 확인</button><button class="btn btn-ghost" id="deviceLogout">로그아웃</button><p id="deviceError" role="status"></p></div></section></div>`;
 document.getElementById('deviceForm').onsubmit=async e=>{e.preventDefault();try{await api.registerDevice(new FormData(e.currentTarget).get('label'));await enterApp();}catch(e){document.getElementById('deviceError').textContent=e.message}};
 document.getElementById('checkDevice').onclick=()=>enterApp().catch(e=>document.getElementById('deviceError').textContent=e.message);
 document.getElementById('deviceLogout').onclick=()=>api.signOut();
}

function renderAccessRequest(){
 app.innerHTML='<div class="login-panel"><div class="login-card"><h2>이용 신청</h2><p>관리자가 승인하기 전에는 회사 재무자료를 볼 수 없습니다.</p><form id="accessForm" class="form-stack"><div class="field"><label>성명</label><input name="full_name" maxlength="100" required autocomplete="name"></div><div class="field"><label>부서</label><input name="department" maxlength="100" required></div><div class="field"><label>이메일</label><input name="email" type="email" required autocomplete="username"></div><div class="field"><label>비밀번호 · 12자 이상</label><input name="password" type="password" minlength="12" required autocomplete="new-password"></div><div class="field"><label>비밀번호 확인</label><input name="confirm_password" type="password" minlength="12" required autocomplete="new-password"></div><button class="btn btn-primary" id="submitAccess">이용 신청</button><button class="btn btn-secondary" type="button" id="backLogin">로그인으로 돌아가기</button><p id="accessMessage" role="status"></p></form></div></div>';
 document.getElementById('backLogin').onclick=renderLogin;
 document.getElementById('accessForm').onsubmit=async e=>{e.preventDefault();const f=formDataObject(e.currentTarget);const message=document.getElementById('accessMessage');const button=document.getElementById('submitAccess');if(f.password!==f.confirm_password){message.textContent='비밀번호 확인이 일치하지 않습니다.';return;}button.disabled=true;try{const data=await api.requestAccess(f);if(data.session){session=data.session;await enterApp();}else{message.textContent='이메일 확인이 필요한 경우 받은 메일의 확인 링크를 누른 후 로그인하세요. 이미 가입한 이메일이라면 기존 계정으로 로그인하세요. 로그인 후 기기를 등록하면 관리자에게 승인을 요청할 수 있습니다.';}}catch(error){message.textContent=/signup|sign.?up.*disabled/i.test(error.message)?'현재 이용 신청이 꺼져 있습니다. 관리자에게 가입 허용 설정을 요청하세요.':error.message;}finally{button.disabled=false;}};
}
function renderPasswordRecovery(){
 app.innerHTML='<div class="login-panel"><form id="newPassword"><h2>비밀번호 재설정</h2><input type="password" name="password" minlength="12" required autocomplete="new-password" placeholder="새 비밀번호 12자 이상"><button class="btn btn-primary">저장</button><p id="passwordError"></p></form></div>';
 document.getElementById('newPassword').onsubmit=async e=>{e.preventDefault();const {error}=await runtime.client.auth.updateUser({password:new FormData(e.currentTarget).get('password')});if(error){document.getElementById('passwordError').textContent=error.message;return}recoveryMode=false;await api.signOut();renderLogin();toast('비밀번호를 변경했습니다. 다시 로그인하세요.');};
}
boot();
